import type { ExecutionLogLine, FirmwareVariant, ReproductionScenario, StepOutcome } from '../types/domain'

/**
 * DEMONSTRATION DATA — the reproduction scenario Revora would generate for INC-001.
 */

const testCode = String.raw`/*
 * test_mqtt_recovery_after_wifi_loss.c
 * Generated by Revora from INC-001 — review before committing.
 *
 * Runs the application's connectivity logic (components/app_connectivity)
 * on the host against simulated Wi-Fi/IP events and an in-process MQTT broker.
 */
#include "unity.h"
#include "harness/net_sim.h"          /* simulated esp_wifi / esp_netif events */
#include "harness/mqtt_broker_sim.h"  /* in-process MQTT 3.1.1 broker          */
#include "harness/clock_sim.h"
#include "app_connectivity.h"
#include "energy_telemetry.h"

static const app_conn_config_t cfg = {
    .wifi_ssid       = "HomeNet-5G",
    .broker_uri      = "mqtt://broker.sim:1883",
    .client_id       = "em200-7f3a",
    .publish_period_ms = 5000,
};

TEST_CASE("mqtt_recovery_after_wifi_loss", "[connectivity][INC-001]")
{
    harness_reset();

    /* 1–2. Initialize application and establish Wi-Fi */
    TEST_ASSERT_EQUAL(ESP_OK, app_connectivity_init(&cfg));
    net_sim_wifi_associate("HomeNet-5G");
    TEST_ASSERT_TRUE(clock_sim_run_until(net_sim_has_ip, 5000));

    /* 3. Connect to MQTT broker */
    TEST_ASSERT_TRUE(clock_sim_run_until(mqtt_broker_sim_client_connected, 5000));

    /* 4. Baseline: telemetry is published */
    TEST_ASSERT_TRUE(clock_sim_run_until(mqtt_broker_sim_received_any, 6000));

    /* 5. Inject unexpected Wi-Fi loss (matches field log: reason 200) */
    net_sim_wifi_drop(WIFI_REASON_BEACON_TIMEOUT);
    clock_sim_advance(10000);

    /* 6–7. Restore network and wait for IP */
    net_sim_wifi_associate("HomeNet-5G");
    TEST_ASSERT_TRUE(clock_sim_run_until(net_sim_has_ip, 5000));
    mqtt_broker_sim_clear_received();

    /* 8–9. Recovery assertion: telemetry must resume within 2 publish periods */
    TEST_ASSERT_TRUE_MESSAGE(
        clock_sim_run_until(mqtt_broker_sim_received_any, 2 * cfg.publish_period_ms),
        "MQTT communication did not recover after Wi-Fi restoration");
}
`

export const scenarios: ReproductionScenario[] = [
  {
    id: 'scn-mqtt-recovery',
    incidentId: 'INC-001',
    testName: 'mqtt_recovery_after_wifi_loss',
    description: 'Drive the application through a Wi-Fi outage matching the field log and assert that MQTT telemetry resumes after the network is restored.',
    environment: {
      target: 'ESP32 Application Logic',
      framework: 'ESP-IDF',
      mode: 'Host-Based Test Harness',
      network: 'Simulated',
      mqttBroker: 'Test Environment',
      firmwareVersion: 'v1.4.2',
      engine: 'demo-simulation',
    },
    targetFailureSignature: [
      'Wi-Fi restored and IP re-acquired',
      'MQTT publish fails after restoration',
      'No MQTT reconnect attempted',
    ],
    testCode,
    steps: [
      { id: 's1', order: 1, kind: 'setup', title: 'Initialize firmware application', detail: 'app_connectivity_init() with production sdkconfig values', derivedFrom: 'sdkconfig.em200.json' },
      { id: 's2', order: 2, kind: 'setup', title: 'Establish Wi-Fi connectivity', detail: 'Simulated STA association to HomeNet-5G', derivedFrom: '10:00:00 Wi-Fi Connected' },
      { id: 's3', order: 3, kind: 'setup', title: 'Connect to MQTT broker', detail: 'In-process broker, MQTT 3.1.1, clean session', derivedFrom: '10:00:02 MQTT Connected' },
      { id: 's4', order: 4, kind: 'assertion', title: 'Verify successful telemetry publication', detail: 'Baseline: at least one publish received by broker', derivedFrom: '10:00:07 Telemetry Published' },
      { id: 's5', order: 5, kind: 'fault', title: 'Inject unexpected Wi-Fi disconnection', detail: 'WIFI_EVENT_STA_DISCONNECTED, reason 200 (BEACON_TIMEOUT)', derivedFrom: '10:00:15 reason=200 BEACON_TIMEOUT' },
      { id: 's6', order: 6, kind: 'action', title: 'Restore network connectivity', detail: 'Re-associate after 10 s outage (matches field log)', derivedFrom: '10:00:25 Wi-Fi Reconnected · 10 s outage' },
      { id: 's7', order: 7, kind: 'action', title: 'Wait for IP address acquisition', detail: 'IP_EVENT_STA_GOT_IP within 5 s', derivedFrom: '10:00:26 IP Address Acquired' },
      { id: 's8', order: 8, kind: 'action', title: 'Attempt MQTT publication', detail: 'Application telemetry loop publishes on its normal period', derivedFrom: '10:00:31 MQTT Publish Failed' },
      { id: 's9', order: 9, kind: 'assertion', title: 'Verify MQTT communication recovers', detail: 'Broker receives telemetry within 2 publish periods', derivedFrom: 'Customer symptom: stops sending measurements' },
    ],
  },
]

export const scenarioById = (id: string) => scenarios.find((s) => s.id === id)

